/**
 * @summary Add a contributor to a temple
 */
export const getAddContributorUrl = (id: number) => {
  return `/api/temples/${id}/contributors`;
};

export const addContributor = async (
  id: number,
  createContributorInput: CreateContributorInput,
  options?: RequestInit,
): Promise<Contributor> => {
  return customFetch<Contributor>(getAddContributorUrl(id), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(createContributorInput),
  });
};

export const getAddContributorMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof addContributor>>,
    TError,
    { id: number; data: BodyType<CreateContributorInput> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof addContributor>>,
  TError,
  { id: number; data: BodyType<CreateContributorInput> },
  TContext
> => {
  const mutationKey = ["addContributor"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof addContributor>>,
    { id: number; data: BodyType<CreateContributorInput> }
  > = (props) => {
    const { id, data } = props ?? {};

    return addContributor(id, data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type AddContributorMutationResult = NonNullable<
  Awaited<ReturnType<typeof addContributor>>
>;
export type AddContributorMutationBody = BodyType<CreateContributorInput>;
export type AddContributorMutationError = ErrorType<unknown>;

/**
 * @summary Add a contributor to a temple
 */
export const useAddContributor = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof addContributor>>,
    TError,
    { id: number; data: BodyType<CreateContributorInput> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationResult<
  Awaited<ReturnType<typeof addContributor>>,
  TError,
  { id: number; data: BodyType<CreateContributorInput> },
  TContext
> => {
  return useMutation(getAddContributorMutationOptions(options));
};

